import{z as s,x as h,o as e,c as l,q as t,j as A,D as E,d as r,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"High-NA 胶厚预算","description":"","frontmatter":{"title":"High-NA 胶厚预算","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-na-resist-budget.md","filePath":"litho/high-na-resist-budget.md","lastUpdated":1791063341000}'),B={name:"litho/high-na-resist-budget.md"};function p(m,a,d,D,C,c){const i=h("Mermaid");return e(),l("div",null,[a[2]||(a[2]=t('<h1 id="high-na-胶厚预算" tabindex="-1">High-NA 胶厚预算 <a class="header-anchor" href="#high-na-胶厚预算" aria-label="Permalink to &quot;High-NA 胶厚预算&quot;">​</a></h1><div class="epigraph"><p>焦深按 $\\mathrm{NA}^2$ 变薄之后，胶膜不再是「够厚才耐刻」的独立规格，而必须和轴向窗口、倒塌深宽比写在同一张预算表上。</p><footer>—— 对照 van Schoot 等对 High-NA 成像与焦深的公开讨论；胶厚与工艺窗口亦见 Levinson</footer></div><p><a href="/litho/high-na-overlay-na">上一课</a>把 High-NA 的横向合同收到套刻：半场拼接、变形倍率下的层间位移，已经是一等良率项。缺口是轴向。硅片侧 NA 从 0.33 到 0.55，<a href="/litho/depth-of-focus">焦深</a>按 \\(\\lambda/\\mathrm{NA}^2\\) 再削一截；胶若仍按 0.33 的厚度涂，膜本身就可能撑满甚至溢出可用焦深，倒塌与刻蚀选择比同时告急。本课钉胶厚预算。变形倍率怎么把半场与写版寻址写进同一张预算，留给<a href="/litho/anamorphic-mask-mag">下一课</a>；真空磁浮台如何把残余离焦压进这张窗，是后面的<a href="/litho/euv-maglev-stage">真空磁浮工件台</a>一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>瑞利式 \\(\\mathrm{DOF}=k_2\\lambda/\\mathrm{NA}^2\\) 在 EUV 真空里 \\(n=1\\)。NA 比 \\(0.55/0.33\\approx 1.67\\)，分母平方约 \\(2.8\\)。公开仿真把 0.55 的可用焦深说成相对 0.33（以及浸没 DUV 习惯的百纳米量级）再掉两到三倍，整体焦点窗可落到数十纳米。胶膜厚度、晶圆台阶、扫描 \\(z\\) 残差必须挤进同一段。</p><p>另一条墙是倒塌。半节距跟 NA 一起缩，线宽往 8 nm 量级走时，深宽比仍想守在约 2:1，膜厚就得掉到约 15–20 nm 一档，而不是 0.33 上常见的三十纳米级。厚胶既吃焦深，又在显影时更容易倒。缺口因此是：薄膜还要转印、还要吸收够光子，不能只报一个「越薄越好」。</p><p><span class="marginnote">数字实例：NA 从 0.33 提到 0.55，\\(\\mathrm{NA}^2\\) 从约 0.109 涨到约 0.303，分母变大 2.8 倍，DOF 就按同一比例缩。假设 0.33 上焦点窗还有 100 nm 量级，0.55 上同一公式给出的就是三十纳米级——胶厚 20 nm 再叠上台阶与残差，窗所剩无几。</span></p><h3 id="胶厚不是刻蚀余量的自由变量" tabindex="-1">胶厚不是刻蚀余量的自由变量 <a class="header-anchor" href="#胶厚不是刻蚀余量的自由变量" aria-label="Permalink to &quot;胶厚不是刻蚀余量的自由变量&quot;">​</a></h3><p>厚胶曾经是硬掩模选择比的保险。High-NA 把保险取消了：成像层必须薄，转印改由底层、含硅硬掩模或金属氧化物胶自身的耐干法来补。把胶厚仍当「刻蚀工程师的独立旋钮」，会在曝光矩阵上先看到窗口消失，再在干法上看到倒线。预算要从成像往下派，而不是从刻蚀往上加。</p><p><span class="marginnote">不要把「High-NA 胶必须 15 nm」写成机台规格。公开讨论的是量级与深宽比逻辑；具体膜厚随层别、CAR 还是金属氧化物、底层栈而变。本课钉的是预算结构，不是某一张涂布配方。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预算拆三块。光学：Bossung 与 E–D 窗的焦轴宽度，必须大于胶厚贡献的「膜内离焦」加上调平残差、场曲与掩模三维引起的最佳焦点漂移。材料：成像层减薄后，吸收截面或底层必须把<a href="/litho/euv-stochastics">随机效应</a>的有效光子数补回来，否则薄胶只是把泊松体积再缩小。转印：成像层之下的转移栈按选择比设计，允许胶在显影后只剩很矮的浮雕。</p><p>工程上常把成像层、底层、硬掩模分开资格认证，而不是把「一张厚 CAR」从 NXE 拷到 EXE。金属氧化物胶的高吸收、高选择比，正是为这张薄预算准备的工作点，见 <a href="/litho/euv-resist">EUV 胶</a>；它不自动放宽焦深，只让薄膜仍能蚀穿。</p><h3 id="深宽比、焦深与光子同时记账" tabindex="-1">深宽比、焦深与光子同时记账 <a class="header-anchor" href="#深宽比、焦深与光子同时记账" aria-label="Permalink to &quot;深宽比、焦深与光子同时记账&quot;">​</a></h3><p>倒塌判据按显影后线高/线宽。焦深判据按空中像沿 \\(z\\) 仍够 NILS 的区间。光子判据按膜内吸收事件数。三张表的交集才是可涂的厚度。只满足倒塌而膜太薄、吸收不够，缺陷率会先于平均 CD 越界；只加厚换光子，焦深与倒塌又先死。</p>',15)),(e(),A(o,null,{default:E(()=>[n(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%8F%AF%E6%B6%82%E5%8E%9A%E5%BA%A6%E5%AE%9A%E5%9C%A8%E5%93%AA%EF%BC%9F%22%5D%20--%3E%20C1%5B%22%E8%86%9C%E5%A4%AA%E5%8E%9A%22%5D%0A%20%20Q%20--%3E%20C2%5B%22%E8%86%9C%E5%A4%AA%E8%96%84%22%5D%0A%20%20C1%20--%3E%20C1a%5B%22%E5%90%83%E6%8E%89%E7%84%A6%E6%B7%B1%EF%BC%8C%E7%84%A6%E7%82%B9%E7%AA%97%E8%A3%85%E4%B8%8D%E4%B8%8B%22%5D%0A%20%20C1%20--%3E%20C1b%5B%22%E6%B7%B1%E5%AE%BD%E6%AF%94%E8%B6%85%202%3A1%EF%BC%8C%E6%98%BE%E5%BD%B1%E5%80%92%E5%A1%8C%22%5D%0A%20%20C2%20--%3E%20C2a%5B%22%E5%90%B8%E6%94%B6%E4%BA%8B%E4%BB%B6%E4%B8%8D%E5%A4%9F%EF%BC%8CLCDU%20%E7%BC%BA%E5%AD%94%E5%8F%98%E5%B7%AE%22%5D%0A%20%20C2%20--%3E%20C2b%5B%22%E8%BD%AC%E5%8D%B0%E6%B5%AE%E9%9B%95%E5%A4%AA%E7%9F%AE%EF%BC%8C%E5%88%BB%E8%9A%80%E6%89%9B%E4%B8%8D%E4%BD%8F%22%5D%0A%20%20C1a%20--%3E%20OK%5B%22%E4%B8%89%E5%88%A4%E6%8D%AE%E4%BA%A4%E9%9B%86%E6%89%8D%E5%8F%AF%E6%B6%82%22%5D%0A%20%20C1b%20--%3E%20OK%0A%20%20C2a%20--%3E%20OK%0A%20%20C2b%20--%3E%20OK%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：把焦深想成走廊的高度，胶厚、晶圆台阶、调平残差都是要在走廊里排队通过的人。走廊从约 100 nm 缩到几十纳米，任何一项超标都会顶穿天花板——这就是为什么胶厚不再是刻蚀工程师一个人的旋钮。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>胶有物理厚度 \\(t\\)。空中像在膜内沿 \\(z\\) 变化，阈值切出来的侧壁是这段积分的结果。\\(t\\) 接近 DOF 时，膜顶与膜底不在同一焦面，侧壁角与 CD 对离焦更敏感，窗口按面积而不是按中心点 CD 收缩。掩模三维还让不同节距的最佳焦点错开，van Schoot 一类 High-NA 成像讨论把这件事与 DOF 放在同一张图上：胶越厚，越吃不起焦点漂移。</p><p>光子面密度由剂量决定，体密度还乘吸收。减 \\(t\\) 而不加吸收或剂量，\\(\\bar N\\) 下降，LCDU 与缺孔变差。所以薄胶预算必须同时改化学或改剂量，不能只改涂布转速。</p><p><span class="marginnote">常见误区：初学者容易把「膜减半」当成只动涂布转速。实际膜厚减半后，膜内吸收的光子事件也近似减半，随机缺陷反而先恶化；正确做法是同步换高吸收的金属氧化物化学或加剂量，让 \\(\\bar N\\) 站得住。</span></p><p><span class="marginnote">Levinson 把工艺窗口写成剂量–焦点平面上的合格区；胶厚进入的是焦轴能否装下膜、台阶与残差。把胶厚只写在材料规格书里、不写进 E–D 窗，等于漏记一维。</span></p>',6)),(e(),A(o,null,{default:E(()=>[n(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22NA%200.55%22%5D%20--%3E%20DOF%5B%22DOF%20%E6%8C%89%20NA%C2%B2%20%E5%8F%98%E8%96%84%22%5D%0A%20%20CD%5B%22%E6%9B%B4%E7%BB%86%E7%BA%BF%E5%AE%BD%22%5D%20--%3E%20AR%5B%22%E6%B7%B1%E5%AE%BD%E6%AF%94%E9%99%90%E5%88%B6%E8%86%9C%E5%8E%9A%22%5D%0A%20%20DOF%20--%3E%20T%5B%22%E6%88%90%E5%83%8F%E5%B1%82%E5%87%8F%E8%96%84%22%5D%0A%20%20AR%20--%3E%20T%0A%20%20T%20--%3E%20ABS%5B%22%E5%90%B8%E6%94%B6%20%2F%20%E5%89%82%E9%87%8F%20%2F%20%E5%BA%95%E5%B1%82%22%5D%0A%20%20T%20--%3E%20ETCH%5B%22%E8%BD%AC%E7%A7%BB%E6%A0%88%E9%80%89%E6%8B%A9%E6%AF%94%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>胶厚预算不替代套刻，也不提高 NA。半场拼接的位移仍按上一课；本课只回答「这一次曝光的膜能不能站在焦深里」。公开文献给的是趋势与仿真量级，不是 EXE 出厂的胶厚表。计量在薄膜上的偏置会变，CD-SEM 与散射测量都要按薄胶重标定，不能沿用 0.33 的厚膜配方。</p><p>后课默认：说到 High-NA 工艺窗口，胶厚已经是焦轴上的一等项，不再把「涂厚一点」当作免费的刻蚀余量。</p><p><span class="marginnote">引用「焦点窗不到 40 nm」一类仿真时写清图形、照明与胶平台。把某一 clips 的数当成所有层的机台规格，会过度悲观或过度乐观。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>High-NA 把 DOF 按 \\(\\mathrm{NA}^2\\) 削薄，胶厚必须进入焦轴预算。</li><li>更细线条把倒塌深宽比也压到薄膜（公开讨论约 15–20 nm 量级）。</li><li>薄胶的光子与转印要靠吸收、剂量和底层补，不能只减涂布厚度。</li><li>掩模三维引起的最佳焦点漂移与膜厚叠加，窗口按面积算。</li><li>出处：van Schoot 等 High-NA 成像与焦深公开论述；Levinson, <em>Principles of Lithography</em>。</li></ul>',6))])}const u=s(B,[["render",p]]);export{g as __pageData,u as default};
